package com.neu.riketiku.shijuan;import static org.assertj.core.api.Assertions.*;import com.neu.riketiku.renzheng.RenZhengYeWuYiChang;import com.neu.riketiku.tiku.admin.AdminQuestionIntegrationTestSupport;import java.math.BigDecimal;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest class PaperServiceIntegrationTest extends AdminQuestionIntegrationTestSupport{@Autowired PaperService service;@Autowired JdbcTemplate jdbc;@Test @Transactional void freezesPublishedQuestionsAndRejectsForeignTeacher(){long teacher=user("paperteacher"),other=user("paperother");jdbc.update("INSERT INTO jiao_shi_dang_an(yong_hu_id,gong_hao,xing_ming) VALUES (?,?,?)",teacher,"T"+teacher,"匿名教师");long profile=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);jdbc.update("INSERT INTO ban_ji(ban_ji_bian_ma,ban_ji_ming_cheng,nian_ji,ru_xue_nian_fen) VALUES (?,?,?,2025)","C"+teacher,"测试班","高二");long cls=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);jdbc.update("INSERT INTO ren_ke_guan_xi(jiao_shi_id,ban_ji_id,ke_mu_id,zhuang_tai,kai_shi_shi_jian) VALUES (?,?,1,'ACTIVE',CURRENT_DATE)",profile,cls);long q=published();var paper=service.save(teacher,new PaperDtos.Save(1L,"期中练习","MANUAL",List.of(new PaperDtos.ItemInput(q,new BigDecimal("5")))));assertThat(paper.totalScore()).isEqualByComparingTo("5");assertThat(paper.questions()).hasSize(1);assertThatThrownBy(()->service.detail(other,paper.id())).isInstanceOf(RenZhengYeWuYiChang.class);assertThatThrownBy(()->service.rule(teacher,new PaperDtos.Rule(1L,"不足",List.of(),List.of("SINGLE_CHOICE"),List.of(5),99,new BigDecimal("100")))).isInstanceOf(RenZhengYeWuYiChang.class).hasMessageContaining("还缺");}
private long user(String p){String s=UUID.randomUUID().toString().replace("-","").substring(0,8);jdbc.update("INSERT INTO yong_hu(yong_hu_ming,mi_ma_zhai_yao) VALUES (?,?)",p+s,"x".repeat(60));return jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}private long published(){String h=UUID.randomUUID().toString().replace("-","");jdbc.update("INSERT INTO ti_mu(ke_mu_id,ti_mu_lei_xing,shi_yong_mo_shi,ti_gan,zheng_que_da_an,nan_du,shi_fou_ke_zi_dong_pan_fen,zhuang_tai,nei_rong_ha_xi) VALUES (1,'SINGLE_CHOICE','ONLINE_PRACTICE','试卷题',JSON_OBJECT('optionLabels',JSON_ARRAY('A')),1,1,'PUBLISHED',?)",h);long q=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);jdbc.update("INSERT INTO ti_mu_xuan_xiang(ti_mu_id,xuan_xiang_biao_shi,xuan_xiang_nei_rong,shi_fou_zheng_que,pai_xu) VALUES (?,'A','对',1,1),(?,'B','错',0,2)",q,q);jdbc.update("INSERT INTO ti_mu_jie_xi(ti_mu_id,jie_xi_lei_xing,jie_xi_nei_rong,ban_ben_hao,zhuang_tai) VALUES (?,'STANDARD','解析',1,'PUBLISHED')",q);return q;}}
